    Lemma relink : forall p A1 M1 A M3 model S P B M R (pc : Z),
      (pc = EXIT_PC /\ S = [] \/ pc = LOOP_PC /\ S <> []) ->
      ainv MI A M model -> mstd model -> umapx MI 24 (nval24 SEGS) A1 M1 obj bl bc ents ->
      lst p M1 P S B A M R ->
      0 < p -> p + 8 * n <= alloc_ceiling -> ~ In p (map fst (live MI A0)) ->
      (forall a : word, ~ Wloop p (bv_unsigned a) -> M a = M3 a) -> (forall a : word, M3 a <> None -> M a <> None) ->
      (forall M' R' P' B',
          lst p M1 P' [] B' A M' R' ->
          (forall a : word, ~ Wloop p (bv_unsigned a) -> M' a = M3 a) -> (forall a : word, M3 a <> None -> M' a <> None) ->
          ainv MI A M' model ->
          srealizes SEGS (cfg fx R' EXIT_PC M' model) K) ->
